import{describe,it,expect}from"vitest";describe("Offline trivia pool",()=>{const e=["India is the only country in the world that is home to both tigers and lions.","The Jantar Mantar observatory in Jaipur features the world's largest stone sundial."];it("picks a random trivia item within bounds",()=>{const t=Math.floor(Math.random()*e.length);expect(t).toBeGreaterThanOrEqual(0),expect(t).toBeLessThan(e.length),expect(e[t]).toBeTruthy()}),it("cycles through trivia correctly",()=>{let t=0;const r=()=>{t=(t+1)%e.length};r(),expect(t).toBe(1),r(),expect(t).toBe(0)})}),describe("Service Worker Precaching",()=>{it("all files defined in STATIC_ASSETS_TO_PRECACHE exist in the repository",()=>{const e=require("fs"),t=require("path"),r=t.resolve(__dirname,"../../sw.js"),i=e.readFileSync(r,"utf8").match(/const STATIC_ASSETS_TO_PRECACHE = \[\s*([\s\S]*?)\s*\];/);expect(i).toBeTruthy();const s=i[1].split(",").map(e=>{let t=e.trim();return(t.startsWith("'")&&t.endsWith("'")||t.startsWith('"')&&t.endsWith('"'))&&(t=t.slice(1,-1)),t.startsWith("./")&&(t=t.slice(2)),t}).filter(e=>e.length>0&&"."!==e);expect(s.length).toBeGreaterThan(0),s.forEach(r=>{const i=t.resolve(__dirname,"../../",r),s=e.existsSync(i);expect(s).toBe(!0)})})});